$ErrorActionPreference='Stop';$u='https://vzbgaldclnsedbjjvykq.supabase.co';$k='sb_publishable_R-bKrL5gZp0IsMRYgYKZSw_zD9EbHqx';$h=@{apikey=$k;Authorization="Bearer $k";Prefer='resolution=merge-duplicates'};do {$m=(Read-Host 'Ваш username').Trim()} while ($m -notmatch '^[A-Za-z0-9_]{3,24}$');function p {$b=@{id=$m;name=$m;last_seen=(Get-Date).ToUniversalTime().ToString('o')}|ConvertTo-Json -Compress;Invoke-RestMethod "$u/rest/v1/presence?on_conflict=id" -Method Post -Headers $h -ContentType application/json -Body $b|Out-Null};while ($true) {try {p;$a=Invoke-RestMethod "$u/rest/v1/presence?select=id,name,last_seen&order=last_seen.desc" -Headers $h;$d=(Get-Date).ToUniversalTime();$l=@($a|Where-Object {($_.id -ne $m) -and (($d-[datetime]$_.last_seen).TotalMinutes -lt 10)})} catch {Write-Host 'Ошибка подключения';continue};Clear-Host;Write-Host "Вы: $m`n`nПользователи онлайн:";$i=1;$l|ForEach-Object {Write-Host "$i. $($_.name)";$i++};if (!$l.Count) {Read-Host 'Никого нет, Enter - обновить'|Out-Null;continue};[int]$n=0;$x=Read-Host 'Выбор (0 - выход)';if ($x -eq 0) {break};if ((-not [int]::TryParse($x,[ref]$n)) -or $n -lt 1 -or $n -gt $l.Count) {continue};$t=(Read-Host "Напишите, что хотите отправить $($l[$n-1].name)").Trim();if (!$t -or $t.Length -gt 1000) {continue};try {$b=@{sender_id=$m;receiver_id=$l[$n-1].id;content=$t}|ConvertTo-Json -Compress;Invoke-RestMethod "$u/rest/v1/messages" -Method Post -Headers $h -ContentType application/json -Body $b|Out-Null;Write-Host success} catch {Write-Host 'Ошибка отправки'};Start-Sleep -Seconds 1}